// The phone film sheet (v3 Task 12 split of js/app.js): engine control rows (option picker, typed values, double-tap
// reset) and the dial view.
// ---------- Film sheet rows: option picker, typed values, double-tap reset ----------
// ↓ imports (generated by the v3 split; edit freely)
import { activeModule, advParams, engine, resetAdvanced, setAdvancedValue, syncAdvancedPanel } from '../engine-host.js';
import { change, commit, snapshot } from '../history.js';
import { syncLooks } from '../looks.js';
import { createOptionPicker } from '../option-picker.js';
import { bindHistorySlider } from './adjust.js';
